   285  int Read4Bytes(FILE *f)
   286  {
   287          // Read 4 bytes (least significant first) into a word
   288          int ix;
   289          unsigned char c;
   290          int acc = 0;
   291
   292          for (ix = 0; ix < 4; ix++) {
   293                  c = fgetc(f) & 0xff;
   294                  acc += (c << (ix*8));
   295          }
   296          return acc;
   297  }
