   299  static int AnnouncePunctuation(Translator *tr, int c1, int *c2_ptr, char *output, int *bufix, int end_clause)
   300  {
   301          // announce punctuation names
   302          // c1:  the punctuation character
   303          // c2:  the following character
   304
   305          int punct_count;
   306          const char *punctname = NULL;
   307          int soundicon;
   308          int attributes;
   309          int short_pause;
   310          int c2;
   311          int len;
   312          int bufix1;
   313          char buf[200];
   314          char buf2[80];
   315          char ph_buf[30];
   316
   317          c2 = *c2_ptr;
   318          buf[0] = 0;
   319
   320          if ((soundicon = LookupSoundicon(c1)) >= 0) {
   321                  // add an embedded command to play the soundicon
   322                  sprintf(buf, "\001%dI ", soundicon);
   323                  UngetC(c2);
   324          } else {
   325                  if ((c1 == '.') && (end_clause) && (c2 != '.')) {
   326                          if (LookupSpecial(tr, "_.p", ph_buf))
   327                                  punctname = ph_buf; // use word for 'period' instead of 'dot'
   328                  }
   329                  if (punctname == NULL)
   330                          punctname = LookupCharName(tr, c1, 0);
   331
   332                  if (punctname == NULL)
   333                          return -1;
   334
   335                  if ((*bufix == 0) || (end_clause == 0) || (tr->langopts.param[LOPT_ANNOUNCE_PUNCT] & 2)) {
   336                          punct_count = 1;
   337                          while ((c2 == c1) && (c1 != '<')) { // don't eat extra '<', it can miss XML tags
   338                                  punct_count++;
   339                                  c2 = GetC();
   340                          }
   341                          *c2_ptr = c2;
   342                          if (end_clause)
   343                                  UngetC(c2);
   344
   345                          if (punct_count == 1)
   346                                  sprintf(buf, " %s", punctname); // we need the space before punctname, to ensure it doesn't merge with the previous word  (eg.  "2.-a")
   347                          else if (punct_count < 4) {
   348                                  buf[0] = 0;
   349                                  if (embedded_value[EMBED_S] < 300)
   350                                          sprintf(buf, "\001+10S"); // Speak punctuation name faster, unless we are already speaking fast.  It would upset Sonic SpeedUp
   351
   352                                  while (punct_count-- > 0) {
   353                                          sprintf(buf2, " %s", punctname);
   354                                          strcat(buf, buf2);
   355                                  }
   356
   357                                  if (embedded_value[EMBED_S] < 300) {
   358                                          sprintf(buf2, " \001-10S");
   359                                          strcat(buf, buf2);
   360                                  }
   361                          } else
   362                                  sprintf(buf, " %s %d %s",
   363                                          punctname, punct_count, punctname);
   364                  } else {
   365                          // end the clause now and pick up the punctuation next time
   366                          UngetC(c2);
   367                          ungot_char2 = c1;
   368                          buf[0] = ' ';
   369                          buf[1] = 0;
   370                  }
   371          }
   372
   373          bufix1 = *bufix;
   374          len = strlen(buf);
   375          strcpy(&output[*bufix], buf);
   376          *bufix += len;
   377
   378          if (end_clause == 0)
   379                  return -1;
   380
   381          if (c1 == '-')
   382                  return CLAUSE_NONE; // no pause
   383
   384          attributes = clause_type_from_codepoint(c1);
   385
   386          short_pause = CLAUSE_SHORTFALL;
   387          if ((attributes & CLAUSE_INTONATION_TYPE) == 0x1000)
   388                  short_pause = CLAUSE_SHORTCOMMA;
   389
   390          if ((bufix1 > 0) && !(tr->langopts.param[LOPT_ANNOUNCE_PUNCT] & 2)) {
   391                  if ((attributes & ~CLAUSE_OPTIONAL_SPACE_AFTER) == CLAUSE_SEMICOLON)
   392                          return CLAUSE_SHORTFALL;
   393                  return short_pause;
   394          }
   395
   396          if (attributes & CLAUSE_TYPE_SENTENCE)
   397                  return attributes;
   398
   399          return short_pause;
   400  }
