   402  int AddNameData(const char *name, int wide)
   403  {
   404          // Add the name to the namedata and return its position
   405          // (Used by the Windows SAPI wrapper)
   406
   407          int ix;
   408          int len;
   409          void *vp;
   410
   411          if (wide) {
   412                  len = (wcslen((const wchar_t *)name)+1)*sizeof(wchar_t);
   413                  n_namedata = (n_namedata + sizeof(wchar_t) - 1) % sizeof(wchar_t);  // round to wchar_t boundary
   414          } else
   415                  len = strlen(name)+1;
   416
   417          if (namedata_ix+len >= n_namedata) {
   418                  // allocate more space for marker names
   419                  if ((vp = realloc(namedata, namedata_ix+len + 1000)) == NULL)
   420                          return -1;  // failed to allocate, original data is unchanged but ignore this new name
   421                  // !!! Bug?? If the allocated data shifts position, then pointers given to user application will be invalid
   422
   423                  namedata = (char *)vp;
   424                  n_namedata = namedata_ix+len + 1000;
   425          }
   426          memcpy(&namedata[ix = namedata_ix], name, len);
   427          namedata_ix += len;
   428          return ix;
   429  }
