   462  int ReadClause(Translator *tr, char *buf, short *charix, int *charix_top, int n_buf, int *tone_type, char *voice_change)
   463  {
   464          /* Find the end of the current clause.
   465              Write the clause into  buf
   466
   467              returns: clause type (bits 0-7: pause x10mS, bits 8-11 intonation type)
   468
   469              Also checks for blank line (paragraph) as end-of-clause indicator.
   470
   471              Does not end clause for:
   472                  punctuation immediately followed by alphanumeric  eg.  1.23  !Speak  :path
   473                  repeated punctuation, eg.   ...   !!!
   474           */
   475
   476          int c1 = ' '; // current character
   477          int c2; // next character
   478          int cprev = ' '; // previous character
   479          int cprev2 = ' ';
   480          int c_next;
   481          int parag;
   482          int ix = 0;
   483          int j;
   484          int nl_count;
   485          int linelength = 0;
   486          int phoneme_mode = 0;
   487          int n_xml_buf;
   488          int terminator;
   489          bool any_alnum = false;
   490          int punct_data = 0;
   491          bool is_end_clause;
   492          int announced_punctuation = 0;
   493          bool stressed_word = false;
   494          int end_clause_after_tag = 0;
   495          int end_clause_index = 0;
   496          wchar_t xml_buf[N_XML_BUF+1];
   497
   498          #define N_XML_BUF2 20
   499          char xml_buf2[N_XML_BUF2+2]; // for &<name> and &<number> sequences
   500          static char ungot_string[N_XML_BUF2+4];
   501          static int ungot_string_ix = -1;
   502
   503          if (clear_skipping_text) {
   504                  skipping_text = false;
   505                  clear_skipping_text = false;
   506          }
   507
   508          tr->phonemes_repeat_count = 0;
   509          tr->clause_upper_count = 0;
   510          tr->clause_lower_count = 0;
   511          *tone_type = 0;
   512
   513          if (ungot_char2 != 0)
   514                  c2 = ungot_char2;
   515          else
   516                  c2 = GetC();
   517
   518          while (!Eof() || (ungot_char != 0) || (ungot_char2 != 0) || (ungot_string_ix >= 0)) {
   519                  if (!iswalnum(c1)) {
   520                          if ((end_character_position > 0) && (count_characters > end_character_position)) {
   521                                  return CLAUSE_EOF;
   522                          }
   523
   524                          if ((skip_characters > 0) && (count_characters >= skip_characters)) {
   525                                  // reached the specified start position
   526                                  // don't break a word
   527                                  clear_skipping_text = true;
   528                                  skip_characters = 0;
   529                                  UngetC(c2);
   530                                  return CLAUSE_NONE;
   531                          }
   532                  }
   533
   534                  cprev2 = cprev;
   535                  cprev = c1;
   536                  c1 = c2;
   537
   538                  if (ungot_string_ix >= 0) {
   539                          if (ungot_string[ungot_string_ix] == 0)
   540                                  ungot_string_ix = -1;
   541                  }
   542
   543                  if ((ungot_string_ix == 0) && (ungot_char2 == 0))
   544                          c1 = ungot_string[ungot_string_ix++];
   545                  if (ungot_string_ix >= 0)
   546                          c2 = ungot_string[ungot_string_ix++];
   547                  else {
   548                          c2 = GetC();
   549
   550                          if (Eof())
   551                                  c2 = ' ';
   552                  }
   553                  ungot_char2 = 0;
   554
   555                  if ((option_ssml) && (phoneme_mode == 0)) {
   556                          if ((c1 == '&') && ((c2 == '#') || ((c2 >= 'a') && (c2 <= 'z')))) {
   557                                  n_xml_buf = 0;
   558                                  c1 = c2;
   559                                  while (!Eof() && (iswalnum(c1) || (c1 == '#')) && (n_xml_buf < N_XML_BUF2)) {
   560                                          xml_buf2[n_xml_buf++] = c1;
   561                                          c1 = GetC();
   562                                  }
   563                                  xml_buf2[n_xml_buf] = 0;
   564                                  c2 = GetC();
   565                                  sprintf(ungot_string, "%s%c%c", &xml_buf2[0], c1, c2);
   566
   567                                  int found = -1;
   568                                  if (c1 == ';') {
   569                                          found = ParseSsmlReference(xml_buf2, &c1, &c2);
   570                                  }
   571
   572                                  if (found <= 0) {
   573                                          ungot_string_ix = 0;
   574                                          c1 = '&';
   575                                          c2 = ' ';
   576                                  }
   577
   578                                  if ((c1 <= 0x20) && ((sayas_mode == SAYAS_SINGLE_CHARS) || (sayas_mode == SAYAS_KEY)))
   579                                          c1 += 0xe000; // move into unicode private usage area
   580                          } else if (c1 == '<') {
   581                                  if ((c2 == '/') || iswalpha(c2) || c2 == '!' || c2 == '?') {
   582                                          // check for space in the output buffer for embedded commands produced by the SSML tag
   583                                          if (ix > (n_buf - 20)) {
   584                                                  // Perhaps not enough room, end the clause before the SSML tag
   585                                                  UngetC(c2);
   586                                                  ungot_char2 = c1;
   587                                                  buf[ix] = ' ';
   588                                                  buf[ix+1] = 0;
   589                                                  return CLAUSE_NONE;
   590                                          }
   591
   592                                          // SSML Tag
   593                                          n_xml_buf = 0;
   594                                          c1 = c2;
   595                                          while (!Eof() && (c1 != '>') && (n_xml_buf < N_XML_BUF)) {
   596                                                  xml_buf[n_xml_buf++] = c1;
   597                                                  c1 = GetC();
   598                                          }
   599                                          xml_buf[n_xml_buf] = 0;
   600                                          c2 = ' ';
   601
   602                                          terminator = ProcessSsmlTag(xml_buf, buf, &ix, n_buf, xmlbase, &audio_text, voice_change, &base_voice, base_voice_variant_name, &ignore_text, &clear_skipping_text, &sayas_mode, &sayas_start, ssml_stack, &n_ssml_stack, &n_param_stack, (int *)speech_parameters);
   603
   604                                          if (terminator != 0) {
   605                                                  buf[ix] = ' ';
   606                                                  buf[ix++] = 0;
   607                                                  return terminator;
   608                                          }
   609                                          c1 = ' ';
   610                                          c2 = GetC();
   611                                          continue;
   612                                  }
   613                          }
   614                  }
   615
   616                  if (ignore_text)
   617                          continue;
   618
   619                  if ((c2 == '\n') && (option_linelength == -1)) {
   620                          // single-line mode, return immediately on NL
   621                          if ((terminator = clause_type_from_codepoint(c1)) == CLAUSE_NONE) {
   622                                  charix[ix] = count_characters - clause_start_char;
   623                                  *charix_top = ix;
   624                                  ix += utf8_out(c1, &buf[ix]);
   625                                  terminator = CLAUSE_PERIOD; // line doesn't end in punctuation, assume period
   626                          }
   627                          buf[ix] = ' ';
   628                          buf[ix+1] = 0;
   629                          return terminator;
   630                  }
   631
   632                  if (c1 == CTRL_EMBEDDED) {
   633                          // an embedded command. If it's a voice change, end the clause
   634                          if (c2 == 'V') {
   635                                  buf[ix++] = 0; // end the clause at this point
   636                                  while (!iswspace(c1 = GetC()) && !Eof() && (ix < (n_buf-1)))
   637                                          buf[ix++] = c1; // add voice name to end of buffer, after the text
   638                                  buf[ix++] = 0;
   639                                  return CLAUSE_VOICE;
   640                          } else if (c2 == 'B') {
   641                                  // set the punctuation option from an embedded command
   642                                  //  B0     B1     B<punct list><space>
   643                                  strcpy(&buf[ix], "   ");
   644                                  ix += 3;
   645
   646                                  if ((c2 = GetC()) == '0')
   647                                          option_punctuation = 0;
   648                                  else {
   649                                          option_punctuation = 1;
   650                                          option_punctlist[0] = 0;
   651                                          if (c2 != '1') {
   652                                                  // a list of punctuation characters to be spoken, terminated by space
   653                                                  j = 0;
   654                                                  while (!iswspace(c2) && !Eof()) {
   655                                                          option_punctlist[j++] = c2;
   656                                                          c2 = GetC();
   657                                                          buf[ix++] = ' ';
   658                                                  }
   659                                                  option_punctlist[j] = 0; // terminate punctuation list
   660                                                  option_punctuation = 2;
   661                                          }
   662                                  }
   663                                  c2 = GetC();
   664                                  continue;
   665                          }
   666                  }
   667
   668                  linelength++;
   669
   670                  if ((j = lookupwchar2(tr->chars_ignore, c1)) != 0) {
   671                          if (j == 1) {
   672                                  // ignore this character (eg. zero-width-non-joiner U+200C)
   673                                  continue;
   674                          }
   675                          c1 = j; // replace the character
   676                  }
   677
   678                  if (iswalnum(c1))
   679                          any_alnum = true;
   680                  else {
   681                          if (stressed_word) {
   682                                  stressed_word = false;
   683                                  c1 = CHAR_EMPHASIS; // indicate this word is stressed
   684                                  UngetC(c2);
   685                                  c2 = ' ';
   686                          }
   687
   688                          if (c1 == 0xf0b)
   689                                  c1 = ' '; // Tibet inter-syllabic mark, ?? replace by space ??
   690
   691                          if (c1 == 0xd4d) {
   692                                  // Malayalam virama, check if next character is Zero-width-joiner
   693                                  if (c2 == 0x200d)
   694                                          c1 = 0xd4e; // use this unofficial code for chillu-virama
   695                          }
   696                  }
   697
   698                  if (iswupper(c1)) {
   699                          tr->clause_upper_count++;
   700
   701                          if ((option_capitals == 2) && (sayas_mode == 0) && !iswupper(cprev)) {
   702                                  char text_buf[30];
   703                                  if (LookupSpecial(tr, "_cap", text_buf) != NULL) {
   704                                          j = strlen(text_buf);
   705                                          if ((ix + j) < n_buf) {
   706                                                  strcpy(&buf[ix], text_buf);
   707                                                  ix += j;
   708                                          }
   709                                  }
   710                          }
   711                  } else if (iswalpha(c1))
   712                          tr->clause_lower_count++;
   713
   714                  if (option_phoneme_input) {
   715                          if (phoneme_mode > 0)
   716                                  phoneme_mode--;
   717                          else if ((c1 == '[') && (c2 == '['))
   718                                  phoneme_mode = -1; // input is phoneme mnemonics, so don't look for punctuation
   719                          else if ((c1 == ']') && (c2 == ']'))
   720                                  phoneme_mode = 2; // set phoneme_mode to zero after the next two characters
   721                  }
   722
   723                  if (c1 == '\n') {
   724                          parag = 0;
   725
   726                          // count consecutive newlines, ignoring other spaces
   727                          while (!Eof() && iswspace(c2)) {
   728                                  if (c2 == '\n')
   729                                          parag++;
   730                                  c2 = GetC();
   731                          }
   732                          if (parag > 0) {
   733                                  // 2nd newline, assume paragraph
   734                                  UngetC(c2);
   735
   736                                  if (end_clause_after_tag)
   737                                          RemoveChar(&buf[end_clause_index]); // delete clause-end punctiation
   738                                  buf[ix] = ' ';
   739                                  buf[ix+1] = 0;
   740                                  if (parag > 3)
   741                                          parag = 3;
   742                                  if (option_ssml) parag = 1;
   743                                  return (CLAUSE_PARAGRAPH-30) + 30*parag; // several blank lines, longer pause
   744                          }
   745
   746                          if (linelength <= option_linelength) {
   747                                  // treat lines shorter than a specified length as end-of-clause
   748                                  UngetC(c2);
   749                                  buf[ix] = ' ';
   750                                  buf[ix+1] = 0;
   751                                  return CLAUSE_COLON;
   752                          }
   753
   754                          linelength = 0;
   755                  }
   756
   757                  announced_punctuation = 0;
   758
   759                  if ((phoneme_mode == 0) && (sayas_mode == 0)) {
   760                          is_end_clause = false;
   761
   762                          if (end_clause_after_tag) {
   763                                  // Because of an xml tag, we are waiting for the
   764                                  // next non-blank character to decide whether to end the clause
   765                                  // i.e. is dot followed by an upper-case letter?
   766
   767                                  if (!iswspace(c1)) {
   768                                          if (!IsAlpha(c1) || !iswlower(c1)) {
   769                                                  UngetC(c2);
   770                                                  ungot_char2 = c1;
   771                                                  buf[end_clause_index] = ' '; // delete the end-clause punctuation
   772                                                  buf[end_clause_index+1] = 0;
   773                                                  return end_clause_after_tag;
   774                                          }
   775                                          end_clause_after_tag = 0;
   776                                  }
   777                          }
